  const getIconColor = (view: ViewState) => {
    if (currentView === view) return isBlackBackground ? 'text-yellow-400' : 'text-green-500';
    return isBlackBackground ? 'text-white' : 'text-gray-500';
  };

  const shadowClass = isBlackBackground 
    ? 'drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]' 
    : '';

  return (
    <div className={`fixed bottom-0 w-full pb-6 pt-4 px-6 flex justify-between items-end z-50 ${isBlackBackground ? 'bg-gradient-to-t from-black/80 to-transparent' : 'bg-white border-t border-gray-100'}`}>

