import React, { useRef, useEffect, useState } from 'react';
import { Camera, RefreshCw, Zap, Image as ImageIcon, Search } from 'lucide-react';

interface CameraViewProps {
  onCapture: (imageSrc: string) => void;
}

export const CameraView: React.FC<CameraViewProps> = ({ onCapture }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [cameraFacingMode, setCameraFacingMode] = useState<'user' | 'environment'>('user');

  useEffect(() => {
    let currentStream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        if (currentStream) {
          currentStream.getTracks().forEach(track => track.stop());
        }

        const constraints = {
          video: {
            facingMode: cameraFacingMode,
            width: { ideal: 1080 },
            height: { ideal: 1920 }
          },
          audio: false
        };

        const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
        currentStream = mediaStream;
        setStream(mediaStream);

        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
          videoRef.current.play();
        }
        setError('');
      } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Camera access denied or unavailable.");
      }
    };

    startCamera();

    return () => {
      if (currentStream) {
        currentStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [cameraFacingMode]);

  const takePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;

      const context = canvas.getContext('2d');
      if (context) {
        // Horizontal flip if using front camera to mirror user
        if (cameraFacingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }

        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const imageSrc = canvas.toDataURL('image/jpeg', 0.9);
        onCapture(imageSrc);
      }
    }
  };

  const flipCamera = () => {
    setCameraFacingMode(prev => prev === 'user' ? 'environment' : 'user');
  };

  return (
    <div className="relative h-full w-full bg-black overflow-hidden rounded-b-xl">
      {error ? (
        <div className="flex h-full items-center justify-center text-center p-6 bg-gray-900 text-white">
          <div>
            <Camera className="w-12 h-12 mx-auto mb-4 text-gray-500" />
            <p>{error}</p>
          </div>
        </div>
      ) : (
        <video 
          ref={videoRef}
          className={`absolute top-0 left-0 w-full h-full object-cover ${cameraFacingMode === 'user' ? 'scale-x-[-1]' : ''}`}
          playsInline
          autoPlay
          muted
        />
      )}

      <canvas ref={canvasRef} className="hidden" />

      {/* Top Controls */}
      <div className="absolute top-4 left-4 z-10 flex flex-col gap-6">
        <button className="bg-black/40 backdrop-blur-md p-2 rounded-full text-white">
            <Search className="w-6 h-6" />
        </button>
      </div>

      <div className="absolute top-4 right-4 z-10 flex flex-col gap-6">
        <button 
            onClick={flipCamera}
            className="bg-black/40 backdrop-blur-md p-2 rounded-full text-white">
          <RefreshCw className="w-6 h-6" />
        </button>
        <button className="bg-black/40 backdrop-blur-md p-2 rounded-full text-white">
          <Zap className="w-6 h-6" />
        </button>
      </div>

      {/* Camera Shutter */}
      <div className="absolute bottom-24 w-full flex justify-center items-center z-20 px-10 gap-8">
        <button className="text-white opacity-80">
             <ImageIcon className="w-8 h-8" />
        </button>

        <button 
          onClick={takePhoto}
          className="w-20 h-20 rounded-full border-4 border-white bg-transparent hover:bg-white/20 active:scale-95 transition-all"
        />

        <div className="w-8 h-8"></div> {/* Spacer for balance */}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { X, Send, Sparkles, Download, Type } from 'lucide-react';
