interface SnapPreviewProps {
  imageSrc: string;
  onClose: () => void;
  onSend: () => void;
}

export const SnapPreview: React.FC<SnapPreviewProps> = ({ imageSrc, onClose, onSend }) => {
  const [caption, setCaption] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showInput, setShowInput] = useState(false);

  const handleAiCaption = async () => {
    setIsGenerating(true);
    const aiText = await generateSnapCaption(imageSrc);
    setCaption(aiText);
    setIsGenerating(false);
    setShowInput(true);
  };

  return (
    <div className="relative h-full w-full bg-black flex flex-col">
      {/* Top Bar */}
      <div className="absolute top-4 left-4 z-50">
        <button onClick={onClose} className="p-2">
            <X className="w-8 h-8 text-white drop-shadow-md" strokeWidth={3} />
        </button>
      </div>

      {/* Main Image */}
      <div className="relative flex-1 bg-black">
        <img src={imageSrc} alt="Snap" className="w-full h-full object-cover" />

        {/* Caption Overlay */}
        {(showInput || caption) && (
            <div 
                className="absolute top-1/2 left-0 w-full bg-black/60 px-4 py-3 flex items-center justify-center cursor-text"
                onClick={() => document.getElementById('caption-input')?.focus()}
            >
                <input 
                    id="caption-input"
                    type="text" 
                    value={caption} 
                    onChange={(e) => setCaption(e.target.value)}
                    className="w-full bg-transparent text-white text-center text-lg outline-none placeholder-gray-300"
                    placeholder="Add a caption..."
                    autoFocus
                />
            </div>
        )}
      </div>

      {/* Side Tools */}
      <div className="absolute top-10 right-4 flex flex-col gap-6 z-40">
        <button className="flex flex-col items-center gap-1" onClick={() => setShowInput(!showInput)}>
            <Type className="w-7 h-7 text-white drop-shadow-md" />
        </button>
        <button className="flex flex-col items-center gap-1">
             <Download className="w-7 h-7 text-white drop-shadow-md" />
        </button>
        <button 
            onClick={handleAiCaption}
            className="flex flex-col items-center gap-1 animate-pulse"
            disabled={isGenerating}
        >
            <div className={`p-2 rounded-full ${isGenerating ? 'bg-yellow-400' : 'bg-transparent'}`}>
                <Sparkles className={`w-7 h-7 text-white drop-shadow-md ${isGenerating ? 'animate-spin' : ''}`} />
            </div>
            <span className="text-white text-[10px] font-bold drop-shadow-md">AI Fix</span>
        </button>
      </div>

      {/* Bottom Send Bar */}
      <div className="absolute bottom-4 right-4 z-50">
        <button 
            onClick={onSend}
            className="bg-yellow-400 text-black font-bold py-3 px-6 rounded-full flex items-center gap-2 shadow-lg hover:scale-105 transition-transform"
        >
            <span>Envoyer</span>
            <Send className="w-5 h-5 -rotate-45 mb-1" strokeWidth={3} />
        </button>
      </div>
    </div>
  );
};

