import React, { useState, useEffect, useRef } from 'react';
import { ChatSession, Message } from '../types';
import { ArrowLeft, Video, Phone, Smile, Camera, Image as ImageIcon, Mic } from 'lucide-react';
import { chatWithGemini } from '../services/geminiService';
import { CURRENT_USER_ID } from '../constants';

interface ChatDetailProps {
  chat: ChatSession;
  onBack: () => void;
}

export const ChatDetail: React.FC<ChatDetailProps> = ({ chat, onBack }) => {
  const [messages, setMessages] = useState<Message[]>(chat.messages);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const isAI = chat.user.id === 'ai';

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!inputText.trim()) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      senderId: CURRENT_USER_ID,
      text: inputText,
      timestamp: new Date(),
      isMe: true,
      type: 'text',
      status: 'sent'
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');

    if (isAI) {
      setIsTyping(true);
      const reply = await chatWithGemini(newMessage.text);
      setIsTyping(false);

      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        senderId: 'ai',
        text: reply,
        timestamp: new Date(),
        isMe: false,
        type: 'text',
        status: 'read'
      };
      setMessages(prev => [...prev, aiMessage]);
    }
  };

  return (
    <div className="h-full bg-white flex flex-col absolute top-0 left-0 w-full z-50">
      {/* Header */}
      <div className="flex items-center px-2 py-2 border-b border-gray-100 bg-white/90 backdrop-blur-md">
        <button onClick={onBack} className="p-2 hover:bg-gray-100 rounded-full">
            <ArrowLeft className="w-7 h-7 text-blue-500" />
        </button>
        <div className="flex items-center flex-1 ml-1">
            <div className="w-10 h-10 rounded-full overflow-hidden mr-2 border border-gray-100">
                <img src={chat.user.avatar} alt="User" className="w-full h-full object-cover" />
            </div>
            <div className="flex flex-col">
                <span className="font-bold text-lg leading-tight">{chat.user.name}</span>
                <span className="text-xs text-gray-500">
                   {isTyping ? 'is typing...' : (isAI ? 'My AI' : 'Snapchat+')}
                </span>
            </div>
        </div>
        <div className="flex gap-1 bg-gray-100 rounded-full p-1">
            <button className="p-2 rounded-full hover:bg-gray-200"><Phone className="w-5 h-5 text-black" /></button>
            <button className="p-2 rounded-full hover:bg-gray-200"><Video className="w-5 h-5 text-black" /></button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 bg-white" ref={scrollRef}>
        {messages.map((msg, idx) => {
            const showAvatar = !msg.isMe && (idx === messages.length - 1 || messages[idx + 1]?.isMe);
            return (
                <div key={msg.id} className={`flex flex-col mb-2 ${msg.isMe ? 'items-end' : 'items-start'}`}>
                     <div className="flex items-end max-w-[80%]">
                        {!msg.isMe && showAvatar && (
                             <img src={chat.user.avatar} className="w-8 h-8 rounded-full mr-2 mb-1 border border-gray-200" alt="avatar" />
                        )}
                        {!msg.isMe && !showAvatar && <div className="w-10"></div>}

                        <div className={`py-2 px-4 text-base relative ${
                            msg.isMe 
                            ? 'bg-blue-500 text-white rounded-l-2xl rounded-tr-2xl rounded-br-sm' 
                            : 'bg-gray-100 text-black rounded-r-2xl rounded-tl-2xl rounded-bl-sm border-l-2 border-red-500' /* Red line like snapchat */
                        }`}>
                            {msg.text}
                        </div>
                     </div>
                </div>
            );
        })}
        {isTyping && (
             <div className="flex items-center ml-10 mt-2">
                 <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce mr-1"></div>
                 <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce mr-1 delay-75"></div>
                 <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-150"></div>
             </div>
        )}
      </div>

      {/* Input */}
      <div className="px-3 py-3 border-t border-gray-100 flex items-center gap-2">
        <button className="p-2 bg-gray-100 rounded-full text-gray-600">
            <Camera className="w-6 h-6" />
        </button>
        <div className="flex-1 bg-gray-100 rounded-full px-4 py-2 flex items-center">
            <input 
                type="text" 
                placeholder="Chat" 
                className="bg-transparent outline-none w-full text-lg"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            />
            <button className="ml-2 text-gray-500"><Smile className="w-6 h-6" /></button>
        </div>
        <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full">
            <Mic className="w-6 h-6" />
        </button>
         <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full">
            <ImageIcon className="w-6 h-6" />
        </button>
      </div>
    </div>
  );
};

