import { SnapPreview } from './components/SnapPreview';
import { Users, Play } from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.CAMERA);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [activeChat, setActiveChat] = useState<ChatSession | null>(null);

  // If in Chat View and a chat is selected, show detail
  if (currentView === ViewState.CHAT && activeChat) {
    return <ChatDetail chat={activeChat} onBack={() => setActiveChat(null)} />;
  }

  // If an image is captured, show the editing preview
  if (capturedImage) {
    return (
      <SnapPreview 
        imageSrc={capturedImage} 
        onClose={() => setCapturedImage(null)} 
        onSend={() => {
            alert("Snap Sent! 🚀");
            setCapturedImage(null);
            setCurrentView(ViewState.CHAT);
        }} 
      />
    );
  }

  const renderContent = () => {
    switch (currentView) {
      case ViewState.MAP:
        return (
            <div className="h-full w-full bg-green-100 flex flex-col items-center justify-center text-green-800">
                <div className="text-6xl mb-4">🌍</div>
                <h2 className="font-bold text-xl">Snap Map</h2>
                <p className="opacity-60">Coming soon</p>
            </div>
        );
      case ViewState.CHAT:
        return <ChatList onSelectChat={setActiveChat} />;
      case ViewState.CAMERA:
        return <CameraView onCapture={setCapturedImage} />;
      case ViewState.STORIES:
        return <StoriesView />;
      case ViewState.SPOTLIGHT:
         return (
            <div className="h-full w-full bg-black flex flex-col items-center justify-center text-white relative">
                <img src="https://picsum.photos/500/900?grayscale" className="absolute w-full h-full object-cover opacity-50" alt="spotlight" />
                <div className="z-10 text-center">
                    <Play className="w-16 h-16 mx-auto mb-4" fill="white" />
                    <h2 className="font-bold text-2xl">Spotlight</h2>
                </div>
            </div>
        );
      default:
        return null;
    }
  };

  const isDarkBackground = currentView === ViewState.CAMERA || currentView === ViewState.SPOTLIGHT;

  return (
    <div className={`h-screen w-screen overflow-hidden flex flex-col ${isDarkBackground ? 'bg-black' : 'bg-white'}`}>
      <main className="flex-1 relative overflow-hidden">
        {renderContent()}
      </main>

      <BottomNav 
        currentView={currentView} 
        onChangeView={(view) => {
            setCurrentView(view);
            setActiveChat(null); // Reset detail view when changing tabs
        }}
        isBlackBackground={isDarkBackground}
      />
    </div>
  );
};

export default App;
